import { customType, timestamp, uuid } from 'drizzle-orm/pg-core';
import { v7 as uuidv7 } from 'uuid';

/** Case-insensitive text (requires the `citext` extension). */
export const citext = customType<{ data: string }>({
  dataType: () => 'citext',
});

/** Full-text search vector. Written by the search module, never by hand. */
export const tsvector = customType<{ data: string }>({
  dataType: () => 'tsvector',
});

/** UUID v7 primary key, generated by the application (time-ordered). */
export const id = () =>
  uuid('id')
    .primaryKey()
    .$defaultFn(() => uuidv7());

/** Tenant column. Every tenant table carries it and is protected by RLS. */
export const siteId = () => uuid('site_id').notNull();

export const createdAt = () =>
  timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
